css:
.scroller {
  height: 200px;
  max-width: 360px;
  overflow: auto;
  border: 1px solid #a1a1aa;
}

.row {
  display: flex;
  min-width: 420px; /* wider than the box, so it scrolls sideways */
  border-bottom: 1px solid #e4e4e7;
}

.cell {
  flex: 1 0 140px;
  min-width: 0;
  padding: 8px 12px;
}

.head {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #18181b;
  color: #fafafa;
  font-weight: 600;
}
